// Extraer datos del webhook de Evolution API v1/v2
const body = items[0].json.body || items[0].json;

// 1. Ignorar mensajes salientes enviados por el propio bot
if ((body.data && body.data.key && body.data.key.fromMe === true) || (body.key && body.key.fromMe === true)) {
  return [];
}

// 2. Extraer teléfono del remitente (normalizado)
let remoteJid = "";
if (body.data && body.data.key && body.data.key.remoteJid) {
  remoteJid = body.data.key.remoteJid;
} else if (body.key && body.key.remoteJid) {
  remoteJid = body.key.remoteJid;
} else if (body.sender) {
  remoteJid = body.sender;
}

const phone = remoteJid.replace(/@.*$/, "").replace(/[^0-9]/g, "");
if (!phone) {
  return [];
}

// 3. Extraer ID del mensaje (para idempotencia)
const messageId = (body.data && body.data.key && body.data.key.id) || (body.key && body.key.id) || undefined;

// 4. Extraer contenido del mensaje según tipo
let messageText = "";
let messageType = "text";
let latitude = undefined;
let longitude = undefined;
let mediaUrl = undefined;
let mediaKey = undefined;
let mimetype = undefined;

const dataObj = body.data || body;
const msgObj = dataObj.message || {};

const instanceName = (dataObj.instance && dataObj.instance.name) || body.instanceName || "control-tower";
const apiKey = "AE24B1606B9B-4393-BB70-7CD18DD40EFD";
const evolutionBase = "https://trafic.generarise.space";

// pickValidBase64: sólo aceptar base64 de tamaño razonable (rechaza thumbnails de 14 bytes)
function pickValidBase64(...candidates) {
  for (const c of candidates) {
    if (typeof c === "string" && c.length > 200) return c;
  }
  return undefined;
}

const directBase64 = pickValidBase64(
  msgObj.base64,
  dataObj.base64,
  msgObj.audioMessage && msgObj.audioMessage.base64,
  msgObj.imageMessage && msgObj.imageMessage.base64,
  msgObj.documentMessage && msgObj.documentMessage.base64
);

// FALLBACK CRÍTICO: si el webhook NO trae base64 válido (caso normal en Evolution
// para audios/imágenes/documentos), pedimos el base64 real a Evolution API.
// Esto resuelve los audios que llegan como un stub de 14 bytes al backend.
async function fetchBase64FromEvolution() {
  if (!messageId || !remoteJid || !apiKey) return null;
  try {
    const res = await this.helpers.httpRequest({
      method: "POST",
      url: `${evolutionBase}/chat/getBase64FromMediaMessage/${instanceName}`,
      headers: { "Content-Type": "application/json", "apikey": apiKey },
      body: {
        message: { key: { remoteJid, fromMe: false, id: messageId } },
        convertToMp4: false
      },
      json: true,
      timeout: 20000
    });
    const b64 = (res && (res.base64 || (res.data && res.data.base64))) || null;
    const mt = (res && (res.mimetype || (res.data && res.data.mimetype))) || null;
    if (b64 && b64.length > 200) return { base64: b64, mimetype: mt };
    return null;
  } catch (e) {
    return null;
  }
}

const isMedia = msgObj.audioMessage || msgObj.imageMessage || msgObj.videoMessage || msgObj.documentMessage || msgObj.stickerMessage;
let evolutionMedia = null;
if (isMedia && !directBase64 && messageId) {
  evolutionMedia = await fetchBase64FromEvolution();
}

const finalBase64 = directBase64 || (evolutionMedia && evolutionMedia.base64);
const finalMime = (evolutionMedia && evolutionMedia.mimetype) || undefined;

function asDataUrl(b64, mt) {
  return `data:${mt || "application/octet-stream"};base64,${b64}`;
}

if (msgObj.conversation) {
  messageText = msgObj.conversation;
  messageType = "text";
} else if (msgObj.extendedTextMessage && msgObj.extendedTextMessage.text) {
  messageText = msgObj.extendedTextMessage.text;
  messageType = "text";
} else if (msgObj.imageMessage) {
  messageText = msgObj.imageMessage.caption || "";
  messageType = "image";
  mediaUrl = finalBase64
    ? asDataUrl(finalBase64, finalMime || msgObj.imageMessage.mimetype || "image/jpeg")
    : (msgObj.imageMessage.url || dataObj.mediaUrl || undefined);
  mediaKey = msgObj.imageMessage.mediaKey || dataObj.mediaKey || body.mediaKey || undefined;
  mimetype = finalMime || msgObj.imageMessage.mimetype || "image/jpeg";
} else if (msgObj.audioMessage) {
  messageType = "audio";
  mediaUrl = finalBase64
    ? asDataUrl(finalBase64, finalMime || msgObj.audioMessage.mimetype || "audio/ogg")
    : (msgObj.audioMessage.url || dataObj.mediaUrl || undefined);
  mediaKey = msgObj.audioMessage.mediaKey || dataObj.mediaKey || body.mediaKey || undefined;
  mimetype = finalMime || msgObj.audioMessage.mimetype || "audio/ogg";
} else if (msgObj.videoMessage) {
  messageText = msgObj.videoMessage.caption || "";
  messageType = "video";
  mediaUrl = finalBase64
    ? asDataUrl(finalBase64, finalMime || msgObj.videoMessage.mimetype || "video/mp4")
    : (msgObj.videoMessage.url || dataObj.mediaUrl || undefined);
  mediaKey = msgObj.videoMessage.mediaKey || dataObj.mediaKey || body.mediaKey || undefined;
  mimetype = finalMime || msgObj.videoMessage.mimetype || "video/mp4";
} else if (msgObj.documentMessage) {
  messageText = msgObj.documentMessage.caption || "";
  messageType = "document";
  mediaUrl = finalBase64
    ? asDataUrl(finalBase64, finalMime || msgObj.documentMessage.mimetype || "application/octet-stream")
    : (msgObj.documentMessage.url || dataObj.mediaUrl || undefined);
  mediaKey = msgObj.documentMessage.mediaKey || dataObj.mediaKey || body.mediaKey || undefined;
  mimetype = finalMime || msgObj.documentMessage.mimetype || "application/octet-stream";
} else if (msgObj.locationMessage || msgObj.liveLocationMessage) {
  const loc = msgObj.locationMessage || msgObj.liveLocationMessage;
  messageType = "location";
  latitude = loc.degreesLatitude;
  longitude = loc.degreesLongitude;
  messageText = loc.name || loc.address || "";
} else {
  messageType = "unknown";
}

return [{
  json: {
    phone,
    remoteJid,
    messageId,
    messageType,
    message: messageText,
    mediaUrl,
    mediaKey,
    mimetype,
    latitude,
    longitude,
    instanceName,
    pushName: dataObj.pushName || body.pushName || undefined,
    rawPayload: JSON.stringify(body)
  }
}];
